INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36711, 'Galatians 3:8', 'Galatians', 3, 8, 'لکه څنګه چې د خدای په کلام کې پېشګویي شوې ده چې خدای به غیریهودیان د ایمان په وسیله نېک وګڼي. هغه ډېر پخوا ابراهیم ته دا زېری ورکړی ؤ او ویلي یې وو: «ستا په وسیله به ټولو قومونو ته برکت ورکړل شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_8.mp3', '', 1761754199, 1761754199),
(36712, 'Galatians 3:9', 'Galatians', 3, 9, 'نو هغه خلک چې ایمان لري، په هغو برکتونو کې به شریک شي چې ابراهیم ته د ایمان له امله ورکړل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_9.mp3', '', 1761754199, 1761754199),
(36713, 'Galatians 3:10', 'Galatians', 3, 10, 'خو هرڅوک چې په شریعت باندې په عمل کولو تکیه کوي هغه لعنتي دی. ځکه چې د خدای په کلام کې لیکل شوي دي: «لعنت به وي په هر هغه چا باندې چې په هغو ټولو شیانو چې په شریعت کې لیکل شوي دي، عمل نه کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_10.mp3', '', 1761754199, 1761754199),
(36714, 'Galatians 3:11', 'Galatians', 3, 11, 'دا ښکاره خبره ده چې هېڅوک د شریعت په وسیله د خدای په نظر کې عادل کېدلی نه شي. ځکه چې د خدای په کلام کې لیکل شوي دي: «نېکان به د ایمان په وسیله ژوند کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_11.mp3', '', 1761754199, 1761754199),
(36715, 'Galatians 3:12', 'Galatians', 3, 12, 'خو د ایمان لاره د شریعت د لارې څخه فرق لري. لکه څنګه چې د خدای په کلام کې لیکل شوي دي: څوک چې په شریعت باندې عمل کوي، هغوی به د شریعت له مخې ژوند کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_12.mp3', '', 1761754199, 1761754199),
(36716, 'Galatians 3:13', 'Galatians', 3, 13, 'خو مسیح مونږ د هغه لعنت نه ازاد کړو چې د شریعت څخه راپیدا کیږي. کله چې هغه په صلیب ځوړند شو، نو زمونږ د ګناهونو لعنت یې په خپل ځان واخیست. ځکه چې د خدای په کلام کې لیکل شوي دي: «هرڅوک چې په ونه کې ځوړند کړای شي هغه لعنتي دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_13.mp3', '', 1761754199, 1761754199),
(36717, 'Galatians 3:14', 'Galatians', 3, 14, 'مسیح دا کار د دې دپاره وکړ چې هغه برکت چې خدای د ابراهیم سره وعده کړې وه د عیسی مسیح په وسیله غیریهودیانو ته هم ورسیږي، ترڅو مونږ د خدای وعده شوی روح القدس د ایمان په وسیله لاسته راوړو. شریعت او د خدای وعده', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_14.mp3', '', 1761754199, 1761754199),
(36718, 'Galatians 3:15', 'Galatians', 3, 15, 'ای زما خویندو او ورونو! زه تاسو ته د ورځني ژوند یو مثال راوړم: هېڅوک نه شي کولای هغه تړون چې د دوه کسانو ترمنځ شوی وي، باطل کړي او یا کوم شی په کې ورزیات کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_15.mp3', '', 1761754199, 1761754199),
(36719, 'Galatians 3:16', 'Galatians', 3, 16, 'خو خدای چې کومه وعده د ابراهیم سره کړې وه، نو د خدای کلام دا نه وایي: «د هغه د اولادونو سره،» یعنې مقصد یې دا نه ؤ چې ډېر اولادونه، بلکې د هغه مقصد دا ؤ چې د هغه یوازېنی اولاد، یعنې د مسیح سره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_16.mp3', '', 1761754199, 1761754199),
(36720, 'Galatians 3:17', 'Galatians', 3, 17, 'زما مقصد دا دی: هغه شریعت چې څلور سوه او دېرش کاله وروسته راغی، نه شي کولای هغه لوظ باطل کړي چې خدای د ابراهیم سره کړی ؤ او نه د هغه وعده ماتولی شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_17.mp3', '', 1761754199, 1761754199),
(36721, 'Galatians 3:18', 'Galatians', 3, 18, 'ځکه که چېرې میراث د شریعت سره تړلی وي، نو هغه نور د وعدې سره تړاو نه لري. خو خدای هغه ابراهیم ته د وعدې له مخې ورکړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_18.mp3', '', 1761754199, 1761754199),
(36722, 'Galatians 3:19', 'Galatians', 3, 19, 'نو بیا د شریعت مقصد څه ؤ؟ د وعدې تر‌څنګ شریعت هم ورکړل شو، ترڅو خلکو ته د هغوی ګناهونه وروښایي. شریعت د دې دپاره جوړ شوی ؤ چې یوازې د ابراهیم د نسل تر راتللو پورې چې وعده یې ورسره شوې وه، اعتبار ولري. خدای خپل شریعت د فرښتو په وسیله موسی ته چې د خدای او انسانانو ترمنځ منځګړی ؤ، ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_19.mp3', '', 1761754199, 1761754199),
(36723, 'Galatians 3:20', 'Galatians', 3, 20, 'خو منځګړي ته هغه وخت اړتیا وي چې په تړون کې دوه خواوې شاملې وي، خو خدای یو دی او هغه د ابراهیم سره بې له منځګړي وعده وکړه. د شریعت مقصد', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_20.mp3', '', 1761754199, 1761754199),
(36724, 'Galatians 3:21', 'Galatians', 3, 21, 'ایا شریعت د خدای د وعدو په خلاف دی؟ هېڅکله نه! ځکه که چېرې شریعت کولای شوای مونږ ته نوی ژوند راکړي، نو په شریعت باندې په عمل کولو سره به د خدای په نظر کې عادل کېدلی شوای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_21.mp3', '', 1761754199, 1761754199),
(36725, 'Galatians 3:22', 'Galatians', 3, 22, 'خو د خدای کلام وایي چې مونږ ټول د ګناه بندیان یو، ترڅو هغه وعده چې په عیسی مسیح باندې په ایمان راوړلو سره تر‌سره کیږي، ایماندارانو ته ورکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_22.mp3', '', 1761754199, 1761754199),
(36726, 'Galatians 3:23', 'Galatians', 3, 23, 'خو په عیسی مسیح باندې په ایمان راوړلو نه مخکې مونږ د شریعت تر قدرت لاندې وو او د شریعت په بند کې ساتل کېدلو، تر هغې پورې چې مونږ ته د عیسی مسیح د ایمان لاره ښکاره شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_23.mp3', '', 1761754199, 1761754199),
(36727, 'Galatians 3:24', 'Galatians', 3, 24, 'نو په دې ډول شریعت د مسیح تر راتللو پورې زمونږ سرپرست ؤ، ترڅو مونږ د ایمان په وسیله نېک وګڼل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_24.mp3', '', 1761754199, 1761754199),
(36728, 'Galatians 3:25', 'Galatians', 3, 25, 'خو څرنګه چې د دې وخت رارسېدلی دی چې په مسیح باندې ایمان راوړو، نو مونږ نور د شریعت سرپرستۍ ته اړتیا نه لرو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_25.mp3', '', 1761754199, 1761754199),
(36729, 'Galatians 3:26', 'Galatians', 3, 26, 'ځکه چې په عیسی مسیح باندې په ایمان راوړلو سره تاسو ټول د خدای اولادونه یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_26.mp3', '', 1761754199, 1761754199),
(36730, 'Galatians 3:27', 'Galatians', 3, 27, 'تاسو ټولو چې د عیسی مسیح په نوم د تعمید غسل واخیست، نو د مسیح خوی او خصلت ولرئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_27.mp3', '', 1761754199, 1761754199),
(36731, 'Galatians 3:28', 'Galatians', 3, 28, 'نو بیا د یهودي او غیریهودي، غلام او ازاد او د نر او ښځې ترمنځ فرق نشته، ځکه چې تاسو ټول په عیسی مسیح کې سره یو یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_28.mp3', '', 1761754199, 1761754199),
(36732, 'Galatians 3:29', 'Galatians', 3, 29, 'که چېرې تاسو د مسیح یئ، نو د ابراهیم اولادونه یئ او د خدای د وعدې له مخې د هغه وارثان یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/galatians3_verse_29.mp3', '', 1761754199, 1761754199),
(36733, 'Revelation 19:1', 'Revelation', 19, 1, 'وروسته له دې ما په اسمان کې د ګڼ شمېر خلکو لوړ اوازونه واورېدل، هغوی نارې وهلې: «د خدای ثنا ووایئ! خلاصون، جلال او قدرت دی زمونږ د خدای', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_1.mp3', '', 1761754199, 1761754199),
(36734, 'Revelation 19:2', 'Revelation', 19, 2, 'ځکه رښتیني او عادلانه دي قضاوتونه د هغه هغه د هغې لویې بدلمنې په هکله چې فاسده یې کړه ځمکه خپلې زناکارۍ باندې ویې کړه پرېکړه د سزا او د هغې څخه یې واخیست بدل د وینې د خپلو خدمتګارانو»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_2.mp3', '', 1761754199, 1761754199),
(36735, 'Revelation 19:3', 'Revelation', 19, 3, 'هغوی چیغې کړې یوځل بیا: «د خدای ثنا ووایئ! ځکه چې تل به پورته کیږي د هغه ښار لوګی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_3.mp3', '', 1761754199, 1761754199),
(36736, 'Revelation 19:4', 'Revelation', 19, 4, 'بیا هغه څلورویشت مشران او څلور اسماني موجودات په ځمکه پرېوتل او خدای ته چې په تخت باندې ناست ؤ په سجده شول، عبادت یې وکړ او ویل یې: «امین، د خدای ثنا ووایئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_4.mp3', '', 1761754199, 1761754199),
(36737, 'Revelation 19:5', 'Revelation', 19, 5, 'بیا د تخت نه یو اواز راغی چې ویل یې: «ای د خدای ټولو خادمانو ټولو خلکو چې وېرېږئ له هغه نه که لویان یئ یا کوچنیان ثنا ووایئ زمونږه د خدای» د وري د واده جشن', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_5.mp3', '', 1761754199, 1761754199),
(36738, 'Revelation 19:6', 'Revelation', 19, 6, 'بیا مې د ډېرو زیاتو خلکو اوازونه واورېدل چې د تېزو اوبو د غرهار او د تندر د لوی ګړزهار په شان وو، چې ویل یې: «د خدای ثنا ووایئ! ځکه چې کاندي پاچاهي زمونږ څښتن مطلق قادر خدای په پوره قدرت سره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_6.mp3', '', 1761754199, 1761754199),
(36739, 'Revelation 19:7', 'Revelation', 19, 7, 'راځئ چې وکړو خوشحالي او خوښ واوسو او بیان کړو لویي د هغه ځکه چې وخت رارسېدلی دی د وري د واده او تیار کړی دی ناوې خپل ځان د هغه دپاره', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_7.mp3', '', 1761754199, 1761754199),
(36740, 'Revelation 19:8', 'Revelation', 19, 8, 'ورکړل شوي دي هغې ته ډېر ښه، ځلېدونکي او پاک کتان کالي چې وایې غوندي.» ښه کتان د خدای د خلکو ښه عملونه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_8.mp3', '', 1761754199, 1761754199),
(36741, 'Revelation 19:9', 'Revelation', 19, 9, 'بیا فرښتې ماته وویل: «دا ولیکه: بختور دي هغه خلک چې د وري د واده مېلمستیا ته وربلل شوي دي.» او همدارنګه هغې وویل: «دا د خدای رښتینی کلام دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_9.mp3', '', 1761754199, 1761754199),
(36742, 'Revelation 19:10', 'Revelation', 19, 10, 'بیا زه د هغې په پښو کې پرېوتم چې سجده ورته وکړم، خو هغې راته وویل: «نه، داسې مه کوه! زه هم ستا او ستا د ورونو په شان د خدای یوه خدمتګاره یم چې په عیسی باندې د خپل ایمان په هکله شاهدي ورکوي، یوازې خدای ته عبادت کوه! ځکه چې د عیسی په هکله شاهدي ورکول د نبوت الهام دی.» په سپین اس باندې سپاره کسان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_10.mp3', '', 1761754199, 1761754199),
(36743, 'Revelation 19:11', 'Revelation', 19, 11, 'بیا ما ولیدل چې اسمان پرانیستل شو او یو سپین اس هلته ولاړ ؤ او هغه کس چې ورباندې سپور ؤ، د هغه نوم «وفادار او رښتینی» ؤ، ځکه چې هغه د عدالت له مخې قضاوت او جنګ کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_11.mp3', '', 1761754199, 1761754199),
(36744, 'Revelation 19:12', 'Revelation', 19, 12, 'د هغه سترګې د اور د لمبو په شان وې او په سر باندې یې ډېر تاجونه وو. په هغو باندې یو نوم لیکل شوی ؤ چې له هغه پرته بل هېڅوک پرې نه پوهېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_12.mp3', '', 1761754199, 1761754199),
(36745, 'Revelation 19:13', 'Revelation', 19, 13, 'هغه په وینو ککړه یوه چپنه اغوستې وه او د هغه نوم «د خدای کلام» ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_13.mp3', '', 1761754199, 1761754199),
(36746, 'Revelation 19:14', 'Revelation', 19, 14, 'اسماني لښکرې چې د سوچه سپین ښه کتان کالي یې اغوستي وو او په سپینو اسونو باندې سپاره وو، هغه پسې روان وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_14.mp3', '', 1761754199, 1761754199),
(36747, 'Revelation 19:15', 'Revelation', 19, 15, 'د هغه د خولې نه یوه تېره توره راووتله چې قومونه پرې ووهي. هغه به د اوسپنې په امسا باندې په هغوی حکومت کوي. هغه به د مطلق قادر خدای د قهر او غضب شراب په خم کې یعنې په هغه لوښي کې چې د انګورو شربت په کې وباسي، تر‌پښو لاندې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_15.mp3', '', 1761754199, 1761754199),
(36748, 'Revelation 19:16', 'Revelation', 19, 16, 'د هغه په چپنه او ورون باندې دا نوم لیکل شوی دی: «د پاچاهانو پاچا او د څښتنانو څښتن.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_16.mp3', '', 1761754199, 1761754199),
(36749, 'Revelation 19:17', 'Revelation', 19, 17, 'بیا ما یوه فرښته ولیدله چې په لمر کې ولاړه وه او په اسمان کې یې الوتونکو مرغانو ته په لوړ اواز نارې کړې: «راشئ او د خدای په لویه مېلمستیا کې سره راټول شئ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_17.mp3', '', 1761754199, 1761754199),
(36750, 'Revelation 19:18', 'Revelation', 19, 18, 'او د پاچاهانو، قومندانانو، جنګیالیو، د اسونو او په هغو باندې د سپرو خلکو غوښې او د ټولو انسانانو که ازاد دي یا غلامان، او که لویان وي یا واړه، غوښې وخورئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_18.mp3', '', 1761754199, 1761754199),
(36751, 'Revelation 19:19', 'Revelation', 19, 19, 'بیا ما ولیدل چې هغه ځناور او د نړۍ پاچاهان او د هغوی لښکرې سره راټولې شوې چې د هغه چا سره چې په اس باندې سپور ؤ او د هغه د لښکرو سره وجنګیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation19_verse_19.mp3', '', 1761754199, 1761754199),
