(36791, 'Matthew 20:6', 'Matthew', 20, 6, 'د مازدیګر شاوخوا پنځه بجې هغه بازار ته لاړ او نور خلک یې ولیدل چې هلته وزګار ولاړ وو. د هغوی څخه یې پوښتنه وکړه: ‹تاسو ولې ټوله ورځ دلته وزګار ولاړ یئ؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_6.mp3', '', 1761754199, 1761754199),
(36792, 'Matthew 20:7', 'Matthew', 20, 7, 'هغوی ځواب ورکړ: ‹ځکه چې مونږ ته هېچا د کار دپاره څه نه دي ویلي.› هغه ورته وویل: ‹تاسو هم لاړ شئ او زما په باغ کې کار وکړئ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_7.mp3', '', 1761754199, 1761754199),
(36793, 'Matthew 20:8', 'Matthew', 20, 8, 'کله چې ماښام شو، نو د باغ خاوند خپل ناظر ته وویل: ‹مزدوران راوغواړه او د هغوی مزدوري ورته ورکړه، لومړی یې هغو خلکو ته ورکړه چې وروسته راغلي دي او بیا ورپسې یې هغو ته ورکړه چې اول راغلي وو.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_8.mp3', '', 1761754199, 1761754199),
(36794, 'Matthew 20:9', 'Matthew', 20, 9, 'کومو خلکو چې شاوخوا پنځه بجې کار پیل کړی ؤ راغلل او د پوره ورځې مزدوري یې واخیستله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_9.mp3', '', 1761754199, 1761754199),
(36795, 'Matthew 20:10', 'Matthew', 20, 10, 'کله چې د هغو مزدورانو وار راورسېد چې اول راغلي وو، نو هغوی په دې تمه وو چې د نورو څخه به زیاته مزدوري واخلي، خو هغوی ته هم د نورو په اندازه ورکړل شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_10.mp3', '', 1761754199, 1761754199),
(36796, 'Matthew 20:11', 'Matthew', 20, 11, 'کله چې هغوی خپله مزدوري واخیستله نو د باغ خاوند ته یې ګیله وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_11.mp3', '', 1761754199, 1761754199),
(36797, 'Matthew 20:12', 'Matthew', 20, 12, 'هغوی وویل: ‹دا خلک چې وروسته راغلل هغوی یوازې یو ساعت کار کړی دی، حال دا چې مونږ ټوله ورځ په سور لمر کې کار کړی دی خو بیاهم تا هغوی ته زمونږ سره یو برابر مزدوري ورکړه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_12.mp3', '', 1761754199, 1761754199),
(36798, 'Matthew 20:13', 'Matthew', 20, 13, 'د باغ خاوند په هغوی کې یو ته وویل: ‹ملګریه! ما درسره کومه بې‌انصافي نه ده کړې. ایا تا خپله دا ونه منله چې په یو دینار به ټوله ورځ کار کوې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_13.mp3', '', 1761754199, 1761754199),
(36799, 'Matthew 20:14', 'Matthew', 20, 14, 'خپله مزدوري دې واخله او ځه. دا زما خوښه ده چې وروسته راغلي سړي ته همدومره ورکړم څومره مې چې تاته درکړله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_14.mp3', '', 1761754199, 1761754199),
(36800, 'Matthew 20:15', 'Matthew', 20, 15, 'ایا زه حق نه لرم چې په خپلو پیسو باندې چې څه غواړم هغه وکړم؟ یا په دې باندې بخیلي کوې چې زه سخي یم؟›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_15.mp3', '', 1761754199, 1761754199),
(36801, 'Matthew 20:16', 'Matthew', 20, 16, 'نو عیسی وویل: «په دې ډول به لومړني وروستي شي او وروستي به اول شي.» عیسی د درېم ځل دپاره د خپل مرګ په هکله پېشګویي کوي (مرقوس ۱۰‏:‌۳۲‌‏-‌۳۴ او لوقا ۱۸‏:‌۳۱‌‏-‌۳۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_16.mp3', '', 1761754199, 1761754199),
(36802, 'Matthew 20:17', 'Matthew', 20, 17, 'کله چې عیسی اورشلیم ته روان ؤ، نو په لاره کې یې خپل دولس شاګردان یوې ګوښې ته کړل او ورته ویې ویل:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_17.mp3', '', 1761754199, 1761754199),
(36803, 'Matthew 20:18', 'Matthew', 20, 18, '«ګورئ، مونږ اوس اورشلیم ته ځو او د انسان زوی به مشرانو کاهنانو او د شریعت عالمانو ته په لاس ورکړل شي او هغوی به ورباندې د مرګ حکم وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_18.mp3', '', 1761754199, 1761754199),
(36804, 'Matthew 20:19', 'Matthew', 20, 19, 'غیریهودیانو ته به یې وسپاري ترڅو هغوی ورباندې ملنډې ووهي، په دورو یې ووهي او په صلیب باندې یې ځوړند کړي. خو په درېمه ورځ به بیا راژوندی شي.» د یوې مور غوښتنه (مرقوس ۱۰‏:‌۳۵‌‏-‌۴۵)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_19.mp3', '', 1761754199, 1761754199),
(36805, 'Matthew 20:20', 'Matthew', 20, 20, 'بیا د زبدي ښځه د خپلو دوو زامنو سره عیسی ته راغله، د هغه په پښو کې پرېوتله او د هغه څخه یې وغوښتل چې په هغې باندې احسان وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_20.mp3', '', 1761754199, 1761754199),
(36806, 'Matthew 20:21', 'Matthew', 20, 21, 'عیسی د هغې څخه پوښتنه وکړه: «څه غواړې؟» هغې وویل: «زما سره وعده وکړه چې ستا په پاچاهۍ کې دې زما دا دواړه زامن ستا په څنګ کې کښېني، یو دې ښي لاس ته کښېني او بل چپ لاس ته.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_21.mp3', '', 1761754199, 1761754199),
(36807, 'Matthew 20:22', 'Matthew', 20, 22, 'عیسی هغوی ته په ځواب کې وویل: «تاسو نه پوهېږئ چې څه غواړئ. کومه پیاله چې زه به یې څښم تاسو هغه څښلی شئ؟» هغوی ځواب ورکړ: «هو، مونږ یې کولای شو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_22.mp3', '', 1761754199, 1761754199),
(36808, 'Matthew 20:23', 'Matthew', 20, 23, 'عیسی هغوی ته وویل: «بې له شکه، تاسو به زما پیاله وڅښئ، خو دا زما په اختیار کې نه ده چې څوک به زما ښي یا چپ لاس ته کښېني. دا ځایونه د هغو خلکو دپاره دي چې زما پلار ورته تیار کړي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_23.mp3', '', 1761754199, 1761754199),
(36809, 'Matthew 20:24', 'Matthew', 20, 24, 'کله چې هغو نورو لسو شاګردانو دا واورېدل، نو هغوی د هغو دوو ورونو څخه خفه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_24.mp3', '', 1761754199, 1761754199),
(36810, 'Matthew 20:25', 'Matthew', 20, 25, 'خو عیسی هغوی راوغوښتل او ورته ویې ویل: «تاسو پوهېږئ چې په نړۍ کې د غیریهودیانو واکمنان په خپلو خلکو باندې باداري کوي او مشران یې ورته خپل زور ښایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew20_verse_25.mp3', '', 1761754199, 1761754199);